examples.template:
MonarchButton(text = action, onClick = { open = true }, variant = MonarchButtonVariant.Warning)
if (open) {
    // While the work runs, a swipe, back or a tap outside does not close the sheet.
    MonarchBottomSheet(onDismissRequest = { open = false }, dismissible = !working) {
        val sheet = this
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            if (!deactivated) {
                // The amber warning badge above the title, as on the web.
                Box(
                    modifier = Modifier
                        .size(MonarchTheme.spacing.space8)
                        .background(MonarchTheme.colors.warningSubtle, MonarchTheme.shapes.full),
                    contentAlignment = Alignment.Center,
                ) {
                    MonarchIcon(imageVector = SampleIcons.Warning, contentDescription = null, tint = MonarchTheme.colors.warningStrong)
                }
            }
            MonarchText(text = "$action $subject?", style = MonarchTextStyle.Title)
            MonarchText(
                text = if (deactivated) {
                    "It starts working again straight away."
                } else {
                    "It stops working until you turn it back on. Nothing is deleted."
                },
                color = MonarchTheme.colors.textMuted,
            )
            if (!deactivated) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(MonarchTheme.colors.bgSubtle, MonarchTheme.shapes.md)
                        .padding(MonarchTheme.spacing.space3),
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                ) {
                    MonarchIcon(imageVector = SampleIcons.Retry, contentDescription = null, size = MonarchIconSize.Sm, tint = MonarchTheme.colors.textMuted)
                    MonarchText(text = "You can reactivate it at any time from $reactivateFrom.")
                }
            }
            MonarchConsequenceList(
                items = if (deactivated) {
                    listOf(MonarchConsequence(MonarchConsequenceKind.Changed, "Shared reports update again"))
                } else {
                    listOf(
                        MonarchConsequence(MonarchConsequenceKind.{{consequences.0.kind|pascal}}, {{consequences.0.label}}),
                        MonarchConsequence(MonarchConsequenceKind.{{consequences.1.kind|pascal}}, {{consequences.1.label}}),
                        MonarchConsequence(MonarchConsequenceKind.{{consequences.2.kind|pascal}}, {{consequences.2.label}}),
                    )
                },
                heading = if (deactivated) "Once it is reactivated" else "While it is deactivated",
            )
            if (asksReason && !deactivated) {
                MonarchTextField(
                    value = reason,
                    onValueChange = { reason = it },
                    label = "Reason (optional)",
                    helperText = "Kept with the change history.",
                    enabled = !working,
                    singleLine = false,
                )
            }
            failure?.let { MonarchInlineNotice(message = it, tone = MonarchTone.Danger) }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2, Alignment.End),
            ) {
                MonarchButton(
                    text = "Cancel",
                    onClick = { open = false },
                    variant = MonarchButtonVariant.Secondary,
                    enabled = !working,
                )
                MonarchButton(
                    text = action,
                    onClick = {
                        working = true
                        failure = null
                        scope.launch {
                            // The app sends the request here, with reason.ifBlank { null }.
                            // On failure: failure = "Couldn’t update the partnership. Try again."
                            working = false
                            deactivated = !deactivated
                            reason = ""
                            sheet.dismiss()
                        }
                    },
                                    variant = MonarchButtonVariant.Danger,
                    loading = working,
                )
            }
        }
    }
}

